import time
from pathlib import Path

class Led:
    def __init__(self, name):
        self.base = Path("/sys/class/leds") / name
        self.max = int((self.base / "max_brightness").read_text())
        (self.base / "trigger").write_text("none")  # reprendre la main

    def set(self, on):
        (self.base / "brightness").write_text(str(self.max if on else 0))

def cpu_temp():
    raw = Path("/sys/class/thermal/thermal_zone0/temp").read_text()
    return int(raw) / 1000

led = Led("led0")
try:
    while True:
        led.set(True); time.sleep(0.2)
        led.set(False); time.sleep(0.8)
        print(f"{cpu_temp():.1f} °C")
except PermissionError:
    print("Accès refusé : lancer avec sudo ou ajouter une règle udev")
finally:
    led.set(False)

